function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
var UTILS=["Electric","Naturalgas","Oil2","Sewer","Water"];
var PIN='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 21s-7-6-7-11a7 7 0 0 1 14 0c0 5-7 11-7 11z"/><circle cx="12" cy="10" r="2.5"/></svg>';
var SEARCH='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#64748b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.5" y2="16.5"/></svg>';

var expanded={}, selId=null, selLabel="", search="", rightTab="accounts", loadingAcct=false;
var filter={ bucket:null, utility:null, status:"all" }; // the matrix cell that scopes the accounts table (UBM defaults to the first card / Total / All)
var lastAccts=[]; // rows currently shown in the accounts table, for the Bill History click lookup
var bhOpen=false; // Bill History modal open/closed
var NODES={}, ROOTS=[];
var selRoot=null, hopen=false, rootInited=false, autoSelDone=false;

function groupCounts(n){
  var directGroups=0, directLocs=0, nestedGroups=0;
  (n.kids||[]).forEach(function(k){ if(k.locId!=null && (!k.kids||!k.kids.length)) directLocs++; else directGroups++; });
  (function rec(x){ (x.kids||[]).forEach(function(k){ if(!(k.locId!=null && (!k.kids||!k.kids.length))) nestedGroups++; rec(k); }); })(n);
  return { directGroups:directGroups, directLocs:directLocs, nestedGroups:nestedGroups, nestedLocs:leafCount(n) };
}

function buildTree(){
  var rows=(appsmith.model&&appsmith.model.tree)||[];
  NODES={}; ROOTS=[];
  rows.forEach(function(r){
    var id=String(r.id);
    NODES[id]={ id:id, parent:(r.parent_id==null?null:String(r.parent_id)), locId:r.location_id,
      label:(r.name&&r.name!=="")?r.name:(r.loc_desc||("Site "+(r.location_id||""))),
      addr:r.service_address, kids:[] };
  });
  rows.forEach(function(r){
    var n=NODES[String(r.id)];
    var pid=(r.parent_id==null?null:String(r.parent_id));
    if(pid!=null && NODES[pid]) NODES[pid].kids.push(n);
    else ROOTS.push(n);
  });
  // sort children by label
  Object.keys(NODES).forEach(function(k){ NODES[k].kids.sort(function(a,b){ return String(a.label).localeCompare(String(b.label),undefined,{numeric:true}); }); });
  ROOTS.sort(function(a,b){ return String(a.label).localeCompare(String(b.label),undefined,{numeric:true}); });
  // default the hierarchy selector to "Facility" if present, else the first root
  if(!rootInited && ROOTS.length){
    rootInited=true;
    var fac=ROOTS.filter(function(r){ return String(r.label).toLowerCase()==="facility"; })[0];
    selRoot=String(fac?fac.id:ROOTS[0].id);
    expanded[selRoot]=true;
  }
  if(selRoot!=null && !NODES[selRoot]) selRoot=(ROOTS[0]?String(ROOTS[0].id):null);
}

function leafIds(n){
  var out=[];
  (function rec(x){ if(x.locId!=null && (!x.kids||!x.kids.length)) out.push(x.locId); (x.kids||[]).forEach(rec); })(n);
  // group nodes may also carry a locId; include any locId in subtree
  var all=[];
  (function rec2(x){ if(x.locId!=null) all.push(x.locId); (x.kids||[]).forEach(rec2); })(n);
  return all.length?all:out;
}
function leafCount(n){
  var s={};
  (function rec(x){ if(x.locId!=null) s[x.locId]=1; (x.kids||[]).forEach(rec); })(n);
  return Object.keys(s).length;
}

function nodeMatches(n,q){
  if(String(n.label).toLowerCase().indexOf(q)>-1) return true;
  return (n.kids||[]).some(function(k){ return nodeMatches(k,q); });
}

function renderNode(n,depth){
  var q=search.trim().toLowerCase();
  if(q && !nodeMatches(n,q)) return "";
  var hasKids=n.kids&&n.kids.length;
  var isOpen = expanded[n.id] || (q?true:false);
  var cnt=leafCount(n);
  var tw = hasKids ? (isOpen?"▾":"▸") : "";
  var icon = (n.locId!=null && !hasKids) ? ('<span class="ico">'+PIN+'</span>') : "";
  var cntHtml = hasKids ? (' <span class="cnt">('+cnt+')</span>') : "";
  var sel=(selId===n.id)?" sel":"";
  var html='<div class="node">'
    +'<div class="row'+sel+'" data-id="'+esc(n.id)+'"><span class="tw" data-tw="'+esc(n.id)+'">'+tw+'</span>'+icon+'<span class="lbl">'+esc(n.label)+cntHtml+'</span></div>';
  if(hasKids && isOpen){
    html+='<div class="kids">'+n.kids.map(function(k){ return renderNode(k,depth+1); }).join('')+'</div>';
  }
  html+='</div>';
  return html;
}

function isOpenStatus(s){ s=String(s||"").toLowerCase(); return s.indexOf("open")>-1 || s==="active"; }
function isClosedStatus(s){ s=String(s||"").toLowerCase(); return s.indexOf("clos")>-1 || s==="inactive"; }

// buckets for the selected node: one per building type present among the node's
// locations. Locations with no building type fall into "Common", matching the
// UBM-native breakdown (Admin office / Classrooms / Common / Gym / Manufacturing plant / ...).
function accountBuckets(selNode, rows){
  var ids={}; leafIds(selNode).forEach(function(id){ ids[String(id)]=1; });
  var groups={}; // label -> rows[]
  rows.forEach(function(r){
    if(!ids[String(r.loc)]) return;
    var raw=(r.btype!=null)?String(r.btype).trim():"";
    // DB stores building types upper-case (ADMIN OFFICE); render sentence-case (Admin office) like UBM.
    // UBM folds the generic "BUILDING" type (and any missing type) into the "Common" bucket.
    var bt = (!raw || raw.toUpperCase()==="BUILDING") ? "Common"
             : (raw.charAt(0).toUpperCase()+raw.slice(1).toLowerCase());
    (groups[bt]=groups[bt]||[]).push(r);
  });
  return Object.keys(groups).map(function(l){ return { label:l, rows:groups[l] }; })
    .sort(function(a,b){ return String(a.label).localeCompare(String(b.label)); });
}

// matrix stats for one building-type bucket from its per-location account rows
function bucketStat(rows){
  var acc={}; // acct -> { open, closed, utils:{} }
  rows.forEach(function(r){
    var a=r.acct; if(a==null) return;
    var key=a+"||"+(r.vendor==null?"":r.vendor); // same billing account under two vendors = two entries (UBM counts a provider switch twice)
    if(!acc[key]) acc[key]={ open:isOpenStatus(r.status), closed:isClosedStatus(r.status), utils:{} };
    String(r.utility||"").split(",").map(function(s){return s.trim();}).filter(Boolean).forEach(function(u){ acc[key].utils[u]=1; });
  });
  var stat={}, totAll=0,totOpen=0,totClosed=0;
  Object.keys(acc).forEach(function(a){
    var o=acc[a].open, c=acc[a].closed; totAll++; if(o) totOpen++; else if(c) totClosed++;
    Object.keys(acc[a].utils).forEach(function(u){
      if(!stat[u]) stat[u]={all:0,open:0,closed:0};
      stat[u].all++; if(o) stat[u].open++; else if(c) stat[u].closed++;
    });
  });
  return { total:{all:totAll,open:totOpen,closed:totClosed}, utils:stat };
}

function matrixHtml(label, st){
  function pill(v,util,status,cls){
    var active=(filter.bucket===label && (filter.utility||null)===(util||null) && filter.status===status);
    return '<span class="pill '+(cls||"")+(v===0?" zero":"")+(active?" active":"")
      +'" data-b="'+esc(label)+'" data-u="'+esc(util||"")+'" data-s="'+status+'">'+v+'</span>';
  }
  var us=Object.keys(st.utils).sort(function(a,b){ return a.localeCompare(b); });
  var h='<div class="mtx"><h4>'+esc(label)+'</h4><div class="matrix">'
    +'<div class="mh l">&nbsp;</div><div class="mh">All</div><div class="mh">Open</div><div class="mh">Closed</div>'
    +'<div class="mc l">Total <span class="i">i</span></div>'
    +'<div class="mc">'+pill(st.total.all,null,"all","tot")+'</div>'
    +'<div class="mc">'+pill(st.total.open,null,"open")+'</div>'
    +'<div class="mc">'+pill(st.total.closed,null,"closed")+'</div>';
  us.forEach(function(u){
    h+='<div class="mc l">'+esc(u)+'</div>'
      +'<div class="mc">'+pill(st.utils[u].all,u,"all")+'</div>'
      +'<div class="mc">'+pill(st.utils[u].open,u,"open")+'</div>'
      +'<div class="mc">'+pill(st.utils[u].closed,u,"closed")+'</div>';
  });
  h+='</div></div>';
  return h;
}

function bucketCards(selNode, rows){
  return accountBuckets(selNode, rows)
    .map(function(b){ return { label:b.label, rows:b.rows, st:bucketStat(b.rows) }; })
    .filter(function(c){ return c.st.total.all>0; });
}

// keep only the account rows matching the active matrix filter (building type + utility + open/closed)
function filterRows(rows, f){
  return rows.filter(function(r){
    if(f.status==="open" && !isOpenStatus(r.status)) return false;
    if(f.status==="closed" && !isClosedStatus(r.status)) return false;
    if(f.utility){
      var us=String(r.utility||"").split(",").map(function(s){ return s.trim(); });
      if(us.indexOf(f.utility)<0) return false;
    }
    return true;
  });
}

// collapse per-location rows into one row per billing account for the table
function groupAccounts(rows){
  var by={};
  rows.forEach(function(r){
    var a=r.acct; if(a==null) return;
    var key=a+"||"+(r.vendor==null?"":r.vendor); // one row per billing account + vendor (UBM lists a provider switch as two rows)
    if(!by[key]) by[key]={ acct:a, vendor:r.vendor, utils:{}, lastbill:r.lastbill, status:r.status, locs:{}, addrs:{}, locId:r.loc };
    String(r.utility||"").split(",").map(function(s){return s.trim();}).filter(Boolean).forEach(function(u){ by[key].utils[u]=1; });
    if(r.locname) by[key].locs[r.locname]=1;
    if(r.addr) by[key].addrs[r.addr]=1;
    if(r.lastbill && (!by[key].lastbill || r.lastbill>by[key].lastbill)) by[key].lastbill=r.lastbill;
  });
  return Object.keys(by).map(function(k){ var x=by[k];
    return { vendor:x.vendor, acct:x.acct, utility:Object.keys(x.utils).sort().join(", "),
      lastbill:x.lastbill, status:x.status, locs:Object.keys(x.locs).join(", "), addr:Object.keys(x.addrs).join(" | "), locId:x.locId };
  }).sort(function(a,b){ return String(a.vendor).localeCompare(String(b.vendor)); });
}

function accountsTable(rows){
  var accts=groupAccounts(rows);
  if(!accts.length) return '<div class="acct-empty">No billing accounts for the selected location.</div>';
  var h='<table><thead><tr><th>Vendor</th><th>Billing Account</th><th>Utility</th><th>Last Bill</th><th>Open/Closed</th><th>Locations</th><th>Service Address</th><th>Details</th></tr></thead><tbody>';
  lastAccts=accts;
  accts.forEach(function(a,i){
    var o=isOpenStatus(a.status);
    var badge='<span class="badge '+(o?"open":"closed")+'">'+esc(a.status||"Unknown")+'</span>';
    h+='<tr>'
      +'<td>'+esc(a.vendor)+'</td>'
      +'<td>'+esc(a.acct)+'</td>'
      +'<td>'+esc(a.utility)+'</td>'
      +'<td class="lastbill">'+esc(a.lastbill||"-")+'</td>'
      +'<td>'+badge+'</td>'
      +'<td>'+esc(a.locs||"")+'</td>'
      +'<td>'+esc(a.addr||"")+'</td>'
      +'<td class="dettd"><span class="link bh" data-idx="'+i+'">Bill History</span></td>'
      +'</tr>';
  });
  h+='</tbody></table>';
  return h;
}

function fmtMoney(v){ if(v==null||v==="") return "-"; var n=Number(v); if(isNaN(n)) return esc(v); return (n<0?"-$":"$")+Math.abs(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}); }
function bhModalHtml(){
  if(!bhOpen) return "";
  var m=appsmith.model||{}; var bh=m.billHistory||{}; var rows=(m.billHistoryRows||[]);
  var body;
  if(m.billHistoryLoading){ body='<div class="bh-empty">Loading bill history\u2026</div>'; }
  else if(!rows.length){ body='<div class="bh-empty">No bills found for this account.</div>'; }
  else {
    body='<table class="bh-tbl"><thead><tr><th>Bill ID</th><th>Invoice Date</th><th>Due Date</th><th class="num">Current Charges</th><th class="num">Past Due</th><th class="num">Total Amount Due</th></tr></thead><tbody>'
      +rows.map(function(r){ return '<tr><td class="bid">'+esc(r["Bill ID"])+'</td><td>'+esc(r["Invoice Date"]||"-")+'</td><td>'+esc(r["Due Date"]||"-")+'</td><td class="num">'+fmtMoney(r["Current Charges"])+'</td><td class="num">'+fmtMoney(r["Past Due"])+'</td><td class="num">'+fmtMoney(r["Total Amount Due"])+'</td></tr>'; }).join('')
      +'</tbody></table>';
  }
  var sub=[bh.vendor,bh.acct].filter(Boolean).map(esc).join(" \u00b7 ");
  return '<div class="bh-back" id="bhback"><div class="bh-modal"><div class="bh-head"><div><div class="bh-title">Bill History</div>'+(sub?'<div class="bh-sub">'+sub+'</div>':'')+'</div><button class="bh-x" id="bhx">\u2715</button></div><div class="bh-body">'+body+'</div><div class="bh-foot"><button class="bh-close" id="bhclose">Close</button></div></div></div>';
}
function hierPopHtml(){
  if(!hopen) return '';
  var opts=ROOTS.map(function(r){
    var on=(selRoot===r.id);
    return '<div class="hopt'+(on?" on":"")+'" data-root="'+esc(r.id)+'"><span>'+esc(r.label)+'</span>'+(on?'<span class="ck">✓</span>':'')+'</div>';
  }).join('');
  return '<div class="hpop" id="hpop">'+opts+'</div>';
}

function render(){
  var m=appsmith.model||{};
  buildTree();

  var curRoot=(selRoot!=null)?NODES[selRoot]:null;
  // by default select the current hierarchy root so its accounts show on load
  if(!autoSelDone && curRoot && !selId){ autoSelDone=true; doSelect(curRoot.id); }
  var curLabel=curRoot?curRoot.label:"Select hierarchy";
