    +'<div class="mc">'+pill(st.total.open,null,"open")+'</div>'
    +'<div class="mc">'+pill(st.total.closed,null,"closed")+'</div>';
  us.forEach(function(u){
    h+='<div class="mc l">'+esc(u)+'</div>'
      +'<div class="mc">'+pill(st.utils[u].all,u,"all")+'</div>'
      +'<div class="mc">'+pill(st.utils[u].open,u,"open")+'</div>'
      +'<div class="mc">'+pill(st.utils[u].closed,u,"closed")+'</div>';
  });
  h+='</div></div>';
  return h;
}

function bucketCards(selNode, rows){
  return accountBuckets(selNode, rows)
    .map(function(b){ return { label:b.label, rows:b.rows, st:bucketStat(b.rows) }; })
    .filter(function(c){ return c.st.total.all>0; });
}

// keep only the account rows matching the active matrix filter (building type + utility + open/closed)
function filterRows(rows, f){
  return rows.filter(function(r){
    if(f.status==="open" && !isOpenStatus(r.status)) return false;
    if(f.status==="closed" && !isClosedStatus(r.status)) return false;
    if(f.utility){
      var us=String(r.utility||"").split(",").map(function(s){ return s.trim(); });
      if(us.indexOf(f.utility)<0) return false;
    }
    return true;
  });
}

// collapse per-location rows into one row per billing account for the table
function groupAccounts(rows){
  var by={};
  rows.forEach(function(r){
    var a=r.acct; if(a==null) return;
    var key=a+"||"+(r.vendor==null?"":r.vendor); // one row per billing account + vendor (UBM lists a provider switch as two rows)
    if(!by[key]) by[key]={ acct:a, vendor:r.vendor, utils:{}, lastbill:r.lastbill, status:r.status, locs:{}, addrs:{}, locId:r.loc };
    String(r.utility||"").split(",").map(function(s){return s.trim();}).filter(Boolean).forEach(function(u){ by[key].utils[u]=1; });
    if(r.locname) by[key].locs[r.locname]=1;
    if(r.addr) by[key].addrs[r.addr]=1;
    if(r.lastbill && (!by[key].lastbill || r.lastbill>by[key].lastbill)) by[key].lastbill=r.lastbill;
  });
  return Object.keys(by).map(function(k){ var x=by[k];
    return { vendor:x.vendor, acct:x.acct, utility:Object.keys(x.utils).sort().join(", "),
      lastbill:x.lastbill, status:x.status, locs:Object.keys(x.locs).join(", "), addr:Object.keys(x.addrs).join(" | "), locId:x.locId };
  }).sort(function(a,b){ return String(a.vendor).localeCompare(String(b.vendor)); });
}

function accountsTable(rows){
  var accts=groupAccounts(rows);
  if(!accts.length) return '<div class="acct-empty">No billing accounts for the selected location.</div>';
  var h='<table><thead><tr><th>Vendor</th><th>Billing Account</th><th>Utility</th><th>Last Bill</th><th>Open/Closed</th><th>Locations</th><th>Service Address</th><th>Details</th></tr></thead><tbody>';
  lastAccts=accts;
  accts.forEach(function(a,i){
    var o=isOpenStatus(a.status);
    var badge='<span class="badge '+(o?"open":"closed")+'">'+esc(a.status||"Unknown")+'</span>';
    h+='<tr>'
      +'<td>'+esc(a.vendor)+'</td>'
      +'<td>'+esc(a.acct)+'</td>'
      +'<td>'+esc(a.utility)+'</td>'
      +'<td class="lastbill">'+esc(a.lastbill||"-")+'</td>'
      +'<td>'+badge+'</td>'
      +'<td>'+esc(a.locs||"")+'</td>'
      +'<td>'+esc(a.addr||"")+'</td>'
      +'<td class="dettd"><span class="link bh" data-idx="'+i+'">Bill History</span></td>'
      +'</tr>';
  });
  h+='</tbody></table>';
  return h;
}

function fmtMoney(v){ if(v==null||v==="") return "-"; var n=Number(v); if(isNaN(n)) return esc(v); return (n<0?"-$":"$")+Math.abs(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}); }
function bhModalHtml(){
  if(!bhOpen) return "";
  var m=appsmith.model||{}; var bh=m.billHistory||{}; var rows=(m.billHistoryRows||[]);
  var body;
  if(m.billHistoryLoading){ body='<div class="bh-empty">Loading bill history\u2026</div>'; }
  else if(!rows.length){ body='<div class="bh-empty">No bills found for this account.</div>'; }
  else {
    body='<table class="bh-tbl"><thead><tr><th>Bill ID</th><th>Invoice Date</th><th>Due Date</th><th class="num">Current Charges</th><th class="num">Past Due</th><th class="num">Total Amount Due</th></tr></thead><tbody>'
      +rows.map(function(r){ return '<tr><td class="bid">'+esc(r["Bill ID"])+'</td><td>'+esc(r["Invoice Date"]||"-")+'</td><td>'+esc(r["Due Date"]||"-")+'</td><td class="num">'+fmtMoney(r["Current Charges"])+'</td><td class="num">'+fmtMoney(r["Past Due"])+'</td><td class="num">'+fmtMoney(r["Total Amount Due"])+'</td></tr>'; }).join('')
      +'</tbody></table>';
  }
  var sub=[bh.vendor,bh.acct].filter(Boolean).map(esc).join(" \u00b7 ");
  return '<div class="bh-back" id="bhback"><div class="bh-modal"><div class="bh-head"><div><div class="bh-title">Bill History</div>'+(sub?'<div class="bh-sub">'+sub+'</div>':'')+'</div><button class="bh-x" id="bhx">\u2715</button></div><div class="bh-body">'+body+'</div><div class="bh-foot"><button class="bh-close" id="bhclose">Close</button></div></div></div>';
}
function hierPopHtml(){
  if(!hopen) return '';
  var opts=ROOTS.map(function(r){
    var on=(selRoot===r.id);
    return '<div class="hopt'+(on?" on":"")+'" data-root="'+esc(r.id)+'"><span>'+esc(r.label)+'</span>'+(on?'<span class="ck">✓</span>':'')+'</div>';
  }).join('');
  return '<div class="hpop" id="hpop">'+opts+'</div>';
}

function render(){
  var m=appsmith.model||{};
  buildTree();

  var curRoot=(selRoot!=null)?NODES[selRoot]:null;
  // by default select the current hierarchy root so its accounts show on load
  if(!autoSelDone && curRoot && !selId){ autoSelDone=true; doSelect(curRoot.id); }
  var curLabel=curRoot?curRoot.label:"Select hierarchy";
  var topbar='<div class="topbar"><div class="hsel"><button class="hbtn" id="hbtn">'+esc(curLabel)+' <span class="chev">▾</span></button>'+hierPopHtml()+'</div></div>';

  // left
  var treeHtml;
  if(!ROOTS.length) treeHtml='<div class="placeholder">No hierarchy for this customer.</div>';
  else if(!curRoot) treeHtml='<div class="placeholder">Select a hierarchy above.</div>';
  else treeHtml=renderNode(curRoot,0);
  var left='<div class="left"><div class="search"><div class="box">'+SEARCH+'<input id="srch" placeholder="Search for a Location" value="'+esc(search)+'"/></div></div>'
    +'<div class="tree" id="tree">'+treeHtml+'</div></div>';

  // right
  var rbody;
  var selNode=(selId!=null)?NODES[selId]:null;
  if(rightTab==="details"){
    if(!selNode){ rbody='<div class="placeholder">Select a node from the tree to view its details.</div>'; }
    else {
      var gc=groupCounts(selNode);
      var totalLoc=Number((m.totalLocations&&m.totalLocations[0]&&(m.totalLocations[0].count||m.totalLocations[0].COUNT))||0);
      var unassigned=Math.max(0, totalLoc - gc.nestedLocs);
      function drow(k,v){ return '<div class="drow"><span class="dk">'+esc(k)+'</span><span class="dv">'+v+'</span></div>'; }
      rbody='<div class="details"><h3>'+esc(selNode.label)+' Location Group Details</h3>'
        +drow("Direct Groups", gc.directGroups)
        +drow("Direct Child Locations", gc.directLocs)
        +drow("Nested Groups", gc.nestedGroups)
        +drow("Nested Locations", gc.nestedLocs)
        +drow("Unassigned Locations", unassigned)
        +'</div>';
    }
  } else if(!selId){
    rbody='<div class="placeholder">Select a location from the tree to view its accounts.</div>';
  } else if(loadingAcct || m.accountsLoading){
    rbody='<div class="placeholder">Loading accounts…</div>';
  } else {
    var rows=(m.accounts||[]);
    var cards=selNode?bucketCards(selNode, rows):[];
    var labels=cards.map(function(c){ return c.label; });
    // default the filter to the first card's Total / All (UBM defaults to "Admin office")
    if(!filter.bucket || labels.indexOf(filter.bucket)<0){ filter.bucket=labels[0]||null; filter.utility=null; filter.status="all"; }
    var mtx=cards.length?('<div class="mtxrow">'+cards.map(function(c){ return matrixHtml(c.label, c.st); }).join('')+'</div>'):'';
    var active=cards.filter(function(c){ return c.label===filter.bucket; })[0];
    var tblRows=active?filterRows(active.rows, filter):[];
    rbody=(mtx||'')+accountsTable(tblRows);
  }
  var right='<div class="right"><div class="subtabs">'
    +'<div class="subtab'+(rightTab==="accounts"?" on":"")+'" data-tab="accounts">Accounts</div>'
    +'<div class="subtab'+(rightTab==="details"?" on":"")+'" data-tab="details">Location Details</div>'
    +'</div><div class="rbody">'+rbody+'</div></div>';

  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="wrap">'+topbar+'<div class="panes">'+left+right+'</div></div>'+bhModalHtml();
  bind();
}

function doSelect(id){
  var n=NODES[id]; if(!n) return;
  selId=id; selLabel=n.label; expanded[id]=true; loadingAcct=true;
  filter={ bucket:null, utility:null, status:"all" };
  appsmith.updateModel({ selIds: leafIds(n).join(","), selLabel: n.label });
  appsmith.triggerEvent("onSelectNode");
}

function pickHierarchy(id){
  if(selRoot!==id){ selRoot=id; expanded[id]=true; doSelect(id); }
  hopen=false; render();
}

function selectNode(id){
  var n=NODES[id]; if(!n) return;
  // click an already-selected node -> unselect and clear the accounts view
  if(selId===id){
    selId=null; selLabel="";
    appsmith.updateModel({ selIds: "", selLabel: "" });
    render();
    return;
  }
  doSelect(id);
  render();
}

function bind(){
  var hb=document.getElementById("hbtn");
  if(hb) hb.onclick=function(ev){ ev.stopPropagation(); hopen=!hopen; render(); };
  var hp=document.getElementById("hpop");
  if(hp){ var os=hp.querySelectorAll("[data-root]");
    for(var a=0;a<os.length;a++){ (function(el){ el.onclick=function(){ pickHierarchy(el.getAttribute("data-root")); }; })(os[a]); } }
  var s=document.getElementById("srch");
  if(s) s.oninput=function(e){ search=e.target.value; var pos=e.target.selectionStart; render(); var s2=document.getElementById("srch"); if(s2){ s2.focus(); try{s2.setSelectionRange(pos,pos);}catch(_){} } };
  var tw=document.querySelectorAll("[data-tw]");
  for(var i=0;i<tw.length;i++){ (function(el){ el.onclick=function(ev){ ev.stopPropagation(); var id=el.getAttribute("data-tw"); expanded[id]=!expanded[id]; render(); }; })(tw[i]); }
  var rows=document.querySelectorAll(".row[data-id]");
  for(var j=0;j<rows.length;j++){ (function(el){ el.onclick=function(){ selectNode(el.getAttribute("data-id")); }; })(rows[j]); }
  var tabs=document.querySelectorAll("[data-tab]");
  for(var k=0;k<tabs.length;k++){ (function(el){ el.onclick=function(){ rightTab=el.getAttribute("data-tab"); render(); }; })(tabs[k]); }
  var pills=document.querySelectorAll(".pill[data-b]");
  for(var p=0;p<pills.length;p++){ (function(el){ el.onclick=function(){ var u=el.getAttribute("data-u"); filter.bucket=el.getAttribute("data-b"); filter.utility=u?u:null; filter.status=el.getAttribute("data-s"); render(); }; })(pills[p]); }
  var bh=document.querySelectorAll(".bh[data-idx]");
  for(var q=0;q<bh.length;q++){ (function(el){ el.onclick=function(){ var a=lastAccts[+el.getAttribute("data-idx")]; if(!a) return; bhOpen=true; appsmith.updateModel({ billHistory:a }); appsmith.triggerEvent("onBillHistory"); render(); }; })(bh[q]); }
  var bx=document.getElementById("bhx"); if(bx) bx.onclick=function(){ bhOpen=false; render(); };
  var bcl=document.getElementById("bhclose"); if(bcl) bcl.onclick=function(){ bhOpen=false; render(); };
  var bbk=document.getElementById("bhback"); if(bbk) bbk.onclick=function(ev){ if(ev.target===bbk){ bhOpen=false; render(); } };
}

appsmith.onReady(function(){ render(); appsmith.onModelChange(function(){ loadingAcct=false; render(); }); });
